    private val minor = Path()
    private val major = Path()

    init {
        for (chunk in DATA) for (line in chunk.split(';')) {
            if (line.isBlank()) continue
            val t = line.trim().split(' ')
            val path = if (t[0] == "M") major else minor
            path.moveTo(t[1].toFloat() / 10f, t[2].toFloat() / 10f)
            var i = 3
            while (i + 1 < t.size) { path.lineTo(t[i].toFloat() / 10f, t[i + 1].toFloat() / 10f); i += 2 }
        }
    }

    /** Dibujar con el origen en el centro del reloj y ya recortado al círculo. */
    fun draw(c: Canvas, p: Paint, majorColor: Int, minorColor: Int) {
        p.style = Paint.Style.STROKE; p.strokeJoin = Paint.Join.ROUND; p.strokeCap = Paint.Cap.ROUND
        p.color = minorColor; p.strokeWidth = 0.7f; c.drawPath(minor, p)
        p.color = majorColor; p.strokeWidth = 1.3f; c.drawPath(major, p)
    }
